    # Use the most frequent nonzero color on each marked diagonal.
    seq = {}
    for d, vals in marks.items():
        seq[d] = max(set(vals), key=vals.count)

    # Repeat the ordered diagonal-color pattern, including the spaces between
    # marked diagonals, across the whole grid.
