    n = len(grid)
    # Each diagonal marker belongs to a line of constant column-row.
    # The three marked lines establish the repeating color sequence.
    colors = {}
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v:
                d = c - r
                colors[d] = v

    # Infer the smallest period consistent with all marked diagonals.
    marked = list(colors.items())
    period = 1
    for p in range(1, 2 * n + 1):
        if all(
            colors[a] == colors[b]
            for a, _ in marked
            for b, _ in marked
            if (a - b) % p == 0
        ):
            period = p
            break

    phase = {}
    for d, v in marked:
        phase[d % period] = v

    # Fill missing phases by cyclically continuing the sequence of observed
    # colors, ordered by their diagonal offsets.
    known = sorted((d % period, v) for d, v in marked)
    for k in range(period):
        if k not in phase:
            phase[k] = min(known, key=lambda kv: min((k-kv[0]) % period,
                                                     (kv[0]-k) % period))[1]

    return [[phase[(c-r) % period] for c in range(n)] for r in range(n)]
